32	/// Physics module demo. 10 balls launch in random directions and bounce inside a
33	/// closed boundary under gravity. The floor adds extra upward speed on contact so
34	/// balls keep oscillating (the demo is self-sustaining, not damped). 7 red balls
35	/// collide with walls AND each other; 3 blue balls only collide with walls
36	/// (layer-isolated from reds; blue↔blue is filtered in the bounce system).
37	///
38	/// Visual feedback (FlashComponent + FlashSystem): a ball blinks a vivid color on
39	/// every impact. The floor is a thick line — cream when the boost is off, green
40	/// when on — and blinks bright green when a ball lands on it while the boost is on.
41	public class PhysicsDemoScreen : IGameScreen
42	{
43	    private const float BoundaryHalfWidth  = 380f;
44	    private const float BoundaryHalfHeight = 220f;
45	    private const float WallThickness      = 20f;
46	
47	    private const float Gravity      = 1200f;    // px/s²
48	    private const float Restitution  = 0.85f;    // wall/ball bounce energy retention
49	    private const float FloorBoost   = 260f;     // extra upward px/s on floor contact
50	    private const float MaxFallSpeed = 1400f;    // safety cap to prevent tunneling
51	
52	    private const float FloorVisualThickness = 6f;     // thick floor line vs the 2px boundary
53	    private const float FlashDuration        = 0.25f;  // seconds for a blink to fade back
54	
55	    private const float MinSpawnSpeed = 120f;    // random initial-velocity speed range
56	    private const float MaxSpawnSpeed = 220f;
57	    private const float MinBallRadius = 10f;     // random per-ball size range
58	    private const float MaxBallRadius = 20f;
59	    // Speed clamp keeps the self-sustaining floor-boost loop from compounding into
60	    // tunnelling speeds. Sits just above a full-height free-fall (~1030 px/s) so
61	    // normal bounces are untouched but runaway energy is capped.
62	    private const float MaxBallSpeed  = 1050f;
63	
64	    private const int DefaultRedCount  = 7;
65	    private const int DefaultBlueCount = 3;
66	    private const int MaxBallsPerColor = 30;     // clamp on the editable counts
67	
68	    /// Floor line tints: regular (boost off), green (boost on), bright blink on a boosted hit.
