70	    private static readonly Color FloorActiveColor  = new(106, 190, 89);
71	    private static readonly Color FloorFlashColor   = new(190, 255, 150);
72	
73	    private const int RedBallLayer  = 0;
74	    private const int BlueBallLayer = 1;
75	    // Walls own both layers so red and blue both collide with them.
