157	    public void ToggleGravity()
158	    {
159	        if (!_gravityToggle.IsAlive || !_gravityToggle.Has<ToggleSwitchComponent>()) return;
160	        var sw = _gravityToggle.Get<ToggleSwitchComponent>();
161	        sw.On = !sw.On;
162	        _gravityOn = sw.On;
163	        _gravityToggle.Set(sw);
164	    }
