167	    {
168	        if (!_floorBoostToggle.IsAlive || !_floorBoostToggle.Has<ToggleSwitchComponent>()) return;
169	        var sw = _floorBoostToggle.Get<ToggleSwitchComponent>();
170	        sw.On = !sw.On;
171	        _floorBoostOn = sw.On;
172	        _floorBoostToggle.Set(sw);
173	        UpdateFloorBaseColor();
