176	    /// Floor line is green while the boost is on, regular cream while it's off.
177	    /// The FlashSystem repaints it to this base color whenever it's not blinking.
178	    private void UpdateFloorBaseColor()
179	    {
180	        if (!_floorVisual.IsAlive || !_floorVisual.Has<FlashComponent>()) return;
181	        ref var flash = ref _floorVisual.Get<FlashComponent>();
182	        flash.BaseColor = _floorBoostOn ? FloorActiveColor : FloorRegularColor;
