195	    /// A random launch velocity: random direction, random speed in the spawn range.
196	    private Vector2 RandomVelocity()
197	    {
198	        var angle = (float)(_rng.NextDouble() * Math.PI * 2.0);
199	        var speed = MinSpawnSpeed + (float)_rng.NextDouble() * (MaxSpawnSpeed - MinSpawnSpeed);
200	        return new Vector2(MathF.Cos(angle) * speed, MathF.Sin(angle) * speed);
201	    }
