208	    private void OnButtonClicked(in DemoButtonClicked msg)
209	    {
210	        // Clicking a number box focuses it (exclusively); clicking anything else
211	        // blurs both so keyboard shortcuts resume.
212	        switch (msg.Id)
213	        {
214	            case RedInputId:  FocusInput(_redInput);  return;
215	            case BlueInputId: FocusInput(_blueInput); return;
216	        }
217	
218	        BlurInputs();
219	        switch (msg.Id)
220	        {
221	            case DemoHeader.BackId: _screenController?.LoadScreen(DemoScreens.Launcher); break;
222	            case DemoHeader.ExitId: _screenController?.Game.Exit(); break;
223	            case "physics.reset":      Reset(); break;
224	            case "physics.pause":      TogglePause(); break;
225	            case "toggle.gravity":     ToggleGravity(); break;
226	            case "toggle.floor-boost": ToggleFloorBoost(); break;
227	        }
228	    }
229	
230	    private void OnTextInputChanged(in TextInputChanged msg)
231	    {
232	        if (msg.Input == _redInput)
233	        {
234	            var n = ParseCount(msg.Text);
235	            if (n == _redCount) return;
236	            _redCount = n;
237	        }
238	        else if (msg.Input == _blueInput)
239	        {
240	            var n = ParseCount(msg.Text);
241	            if (n == _blueCount) return;
242	            _blueCount = n;
243	        }
244	        else return;
245	
246	        RebuildBalls();
247	    }
