266	    /// Mirrors focus onto both the input's key-capture flag and its button accent
267	    /// (IsActive drives the focused border/text color via DemoButtonInteractionSystem).
268	    private static void SetFocus(Entity input, bool focused)
269	    {
270	        if (!input.IsAlive) return;
271	        if (input.Has<TextInputComponent>())
272	        {
273	            ref var ti = ref input.Get<TextInputComponent>();
274	            ti.Focused = focused;
