285	    private void CreateBoundary()
286	    {
287	        var bounds = new Rectangle(
288	            -(int)BoundaryHalfWidth, -(int)BoundaryHalfHeight,
289	            (int)BoundaryHalfWidth * 2, (int)BoundaryHalfHeight * 2);
290	
291	        var boundary = _world.CreateEntity();
292	        boundary.Set(new TransformComponent(Vector2.Zero));
293	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.2f };
294	        draw.SetMeshData(new RectangleOutlineMeshGenerator(bounds, thickness: 2f, color: SproutPalette.TextLight));
295	        boundary.Set(draw);
296	        boundary.Set<VisibleComponent>();
297	    }
