299	    /// Thick horizontal line drawn over the boundary's bottom edge — the floor's
300	    /// visual. Regular cream when the boost is off, green when on, and it blinks
301	    /// bright (via FlashSystem) when a ball lands on it while the boost is on.
302	    /// Sits at LayerDepth 0.25 — above the boundary outline (0.2), below the balls.
303	    private void CreateFloorVisual()
304	    {
305	        var left  = new Vector2(-BoundaryHalfWidth, BoundaryHalfHeight);
306	        var right = new Vector2( BoundaryHalfWidth, BoundaryHalfHeight);
307	        var baseColor = _floorBoostOn ? FloorActiveColor : FloorRegularColor;
308	
309	        var floor = _world.CreateEntity();
310	        floor.Set(new TransformComponent(Vector2.Zero));
311	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.25f };
312	        draw.SetMeshData(new LineMeshGenerator(left, right, FloorVisualThickness, baseColor));
313	        floor.Set(draw);
314	        floor.Set(new FlashComponent(baseColor, FloorFlashColor, FlashDuration));
315	        floor.Set<VisibleComponent>();
316	        _floorVisual = floor;
317	    }
318	
319	    /// Four BoxColliders forming a closed box just outside the visible boundary.
320	    /// Walls share both red and blue layers so both ball categories collide with
321	    /// them. Walls have zero TransformComponent.Delta so even though they're
322	    /// active colliders, the swept test self-skips when they iterate as entity A.
323	    private void CreateWalls()
324	    {
325	        var redAndBlue = new HashSet<int> { RedBallLayer, BlueBallLayer };
326	
327	        // Floor — tagged so the bounce system can apply the extra upward kick.
328	        var floor = CreateWall(new Rectangle(
329	            -(int)(BoundaryHalfWidth + WallThickness),
330	            (int)BoundaryHalfHeight,
331	            (int)((BoundaryHalfWidth + WallThickness) * 2),
332	            (int)WallThickness), redAndBlue);
333	        floor.Set<FloorTag>();
334	
335	        // Ceiling
336	        CreateWall(new Rectangle(
337	            -(int)(BoundaryHalfWidth + WallThickness),
338	            -(int)(BoundaryHalfHeight + WallThickness),
339	            (int)((BoundaryHalfWidth + WallThickness) * 2),
340	            (int)WallThickness), redAndBlue);
341	
342	        // Left wall
343	        CreateWall(new Rectangle(
344	            -(int)(BoundaryHalfWidth + WallThickness),
345	            -(int)BoundaryHalfHeight,
346	            (int)WallThickness,
347	            (int)BoundaryHalfHeight * 2), redAndBlue);
348	
349	        // Right wall
350	        CreateWall(new Rectangle(
351	            (int)BoundaryHalfWidth,
352	            -(int)BoundaryHalfHeight,
353	            (int)WallThickness,
354	            (int)BoundaryHalfHeight * 2), redAndBlue);
355	    }
356	
357	    private Entity CreateWall(Rectangle bounds, HashSet<int> activeLayers)
358	    {
359	        var wall = _world.CreateEntity();
360	        wall.Set(new TransformComponent(Vector2.Zero));
361	        wall.Set(new BoxColliderComponent(bounds, activeLayers));
362	        return wall;
363	    }
