365	    /// Despawns the current balls and spawns a fresh random set matching the
366	    /// current red/blue counts. Called on load, on reset, and whenever a count
367	    /// input changes.
368	    private void RebuildBalls()
369	    {
370	        foreach (var ball in _balls)
371	            if (ball.IsAlive) ball.Dispose();
372	        _balls.Clear();
373	
374	        for (var i = 0; i < _redCount; i++)  _balls.Add(CreateBall(BallType.Red));
375	        for (var i = 0; i < _blueCount; i++) _balls.Add(CreateBall(BallType.Blue));
376	    }
377	
378	    private Entity CreateBall(BallType type)
379	    {
380	        var radius = MinBallRadius + (float)_rng.NextDouble() * (MaxBallRadius - MinBallRadius);
381	        var spawn = RandomSpawn(radius);
382	
383	        var entity = _world.CreateEntity();
384	        entity.Set(new TransformComponent(spawn));
385	        entity.Set(new VelocityComponent(RandomVelocity()));
386	        entity.Set(new RigidBodyComponent(mass: 1f));
387	        entity.Set(new BallTagComponent { Type = type });
388	
389	        // Octagonal convex collider as a circle approximation. SAT handles
390	        // polygon-polygon collisions natively, so ball↔ball bounces look round
391	        // rather than square.
392	        var layer = type == BallType.Red ? RedBallLayer : BlueBallLayer;
393	        entity.Set(new ConvexColliderComponent(
394	            CircleVertices(radius, segments: 8),
395	            activeLayers: new HashSet<int> { layer }));
396	
397	        // Resting tint + the vivid color the ball blinks to on impact (FlashSystem).
398	        var (color, flashColor) = type == BallType.Red
399	            ? (SproutPalette.Crimson, new Color(255, 90, 80))
400	            : (SproutPalette.SkyBlue, new Color(150, 230, 255));
401	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.95f };
402	        draw.SetMeshData(new CircleMeshGenerator(Vector2.Zero, radius, color, segments: 24));
403	        entity.Set(draw);
404	        entity.Set(new FlashComponent(color, flashColor, FlashDuration));
405	        entity.Set<VisibleComponent>();
406	        return entity;
407	    }
408	
409	    /// A random spawn point inside the boundary, kept a ball-radius clear of the walls.
410	    private Vector2 RandomSpawn(float radius)
411	    {
412	        var margin = radius + 8f;
413	        var x = MathHelper.Lerp(-BoundaryHalfWidth + margin,  BoundaryHalfWidth - margin,  (float)_rng.NextDouble());
414	        var y = MathHelper.Lerp(-BoundaryHalfHeight + margin, BoundaryHalfHeight - margin, (float)_rng.NextDouble());
415	        return new Vector2(x, y);
416	    }
417	
418	    private static Vector2[] CircleVertices(float radius, int segments)
419	    {
420	        var verts = new Vector2[segments];
421	        for (var i = 0; i < segments; i++)
422	        {
423	            var a = MathF.PI * 2f * i / segments;
424	            verts[i] = new Vector2(MathF.Cos(a) * radius, MathF.Sin(a) * radius);
425	        }
426	        return verts;
427	    }
