557	    /// Adapter to the `CreateCollisionMessageDelegate<CollisionMessage>` shape that
558	    /// `TransformCollisionDetectionSystem` expects. Always emits Physics-type messages.
559	    private static CollisionMessage CreateCollisionMessage(
560	        Entity entity, Entity target,
561	        Vector2 contactPoint, Vector2 contactNormal,
562	        float contactTime, float penetrationDepth, int layer)
563	        => new(entity, target, contactPoint, contactNormal, contactTime, penetrationDepth, layer, CollisionType.Physics);
564	
565	    private SequentialSystem<GameState> CreateUpdateSystem()
566	    {
567	        // Reference physics pipeline order (per docs/CORE_TENETS.md §5):
568	        //   Movement → Velocity → Detection → Resolution → Commit
569	        // Movement here is gravity-only; ball↔ball/ball↔wall bouncing is the
570	        // custom resolution stage that subscribes to CollisionMessage.
571	        return new SequentialSystem<GameState>(
572	            new CursorInputSystem(_world),
573	            new IntrinsicSizingSystem(_world),
574	            new AutoLayoutSystem(_world, _viewportManager),
575	            new DemoButtonInteractionSystem(_world),
576	            new TextInputSystem(_world),
577	            new DemoIconRecolorSystem(_world),
578	            new ToggleSwitchSystem(_world),
579	            new PhysicsDemoInputSystem(this),
580	            new GatedGravitySystem(_world, _runner, this),
581	            new GatedVelocitySystem(_world, _runner, this),
582	            new TransformCollisionDetectionSystem<CollisionMessage>(_world, CreateCollisionMessage),
583	            new BallBounceSystem(_world, this),
584	            new BallSpeedClampSystem(_world, MaxBallSpeed),
585	            new FlashSystem(_world),
586	            new TransformCommitSystem(_world, _runner),
587	            new HierarchySystem(_world),
588	            new CursorPositionSystem(_world, _camera, _viewportManager),
589	            new CursorDrawPrepSystem(_world));
590	    }
591	
592	    private SequentialSystem<GameState> CreateDrawSystem()
593	    {
594	        return new SequentialSystem<GameState>(
595	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering: false),
596	            new TextPrepSystem(_world, pixelPerfectRendering: false),
597	            new MeshPrepSystem(_world),
598	            new ButtonMeshPrepSystem(_world),
599	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
600	                RenderTargetID.Main, _renderTargets[RenderTargetID.Main], _camera),
601	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
602	                RenderTargetID.UI, _renderTargets[RenderTargetID.UI]),
603	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
604	                RenderTargetID.HUD, _renderTargets[RenderTargetID.HUD]),
605	            new FinalDrawSystem(_spriteBatch, _graphicsDevice, _viewportManager, new[]
606	            {
607	                RenderLayer.Main(_renderTargets[RenderTargetID.Main]),
608	                RenderLayer.UI(_renderTargets[RenderTargetID.UI]),
609	                RenderLayer.HUD(_renderTargets[RenderTargetID.HUD]),
610	            }));
611	    }
612	
613	    public void Dispose()
614	    {
615	        UpdateSystem.Dispose();
616	        DrawSystem.Dispose();
617	        foreach (var rt in _renderTargets.Values) rt.Dispose();
618	        _world.Dispose();
619	        GC.SuppressFinalize(this);
620	    }
621	}
622	
623	// ─── tags + data ──────────────────────────────────────────────────────────
624	
625	public enum BallType { Red, Blue }
626	
627	public struct BallTagComponent { public BallType Type; }
628	
629	/// Marks the bottom wall so the bounce system can add the upward kick that
630	/// keeps the demo perpetual.
631	public struct FloorTag { }
632	
633	/// Demo-local "blink on impact" tint for any mesh entity. <see cref="FlashSystem"/>
634	/// lerps the mesh's vertex colors from <see cref="FlashColor"/> back to
635	/// <see cref="BaseColor"/> as <see cref="Remaining"/> decays to zero; setting
636	/// <c>Remaining = Duration</c> (re)triggers the blink. Pure data — the system owns
637	/// the timing and the vertex writes.
638	public struct FlashComponent
639	{
640	    public Color BaseColor;
641	    public Color FlashColor;
642	    public float Duration;
643	    public float Remaining;
644	
645	    public FlashComponent(Color baseColor, Color flashColor, float duration)
646	    {
647	        BaseColor = baseColor;
648	        FlashColor = flashColor;
649	        Duration = duration;
650	        Remaining = 0f;
651	    }
652	}
653	
654	// ─── input ────────────────────────────────────────────────────────────────
655	
656	/// Edge-triggered keyboard shortcuts for the physics demo.
657	public class PhysicsDemoInputSystem : ISystem<GameState>
658	{
659	    private readonly PhysicsDemoScreen _screen;
660	    private KeyboardState _previous;
661	    public bool IsEnabled { get; set; } = true;
662	
663	    public PhysicsDemoInputSystem(PhysicsDemoScreen screen)
664	    {
665	        _screen = screen;
666	        _previous = Keyboard.GetState();
667	    }
668	
669	    public void Update(GameState state)
670	    {
671	        if (!IsEnabled) return;
672	        var current = Keyboard.GetState();
673	        bool Pressed(Keys k) => current.IsKeyDown(k) && !_previous.IsKeyDown(k);
674	
675	        if (Pressed(Keys.R)) _screen.Reset();
676	        if (Pressed(Keys.Space)) _screen.TogglePause();
677	        if (Pressed(Keys.G)) _screen.ToggleGravity();
678	        if (Pressed(Keys.F)) _screen.ToggleFloorBoost();
679	        if (Pressed(Keys.Escape)) _screen.GoBackToLauncher();
680	
681	        _previous = current;
682	    }
683	
684	    public void Dispose() => GC.SuppressFinalize(this);
685	}
