687	// ─── physics systems (gated by demo state) ────────────────────────────────
688	
689	/// Wraps the engine's GravitySystem so it can be paused or toggled off by the
690	/// demo without re-registering the system on toggle.
691	public class GatedGravitySystem : ISystem<GameState>
692	{
693	    private readonly GravitySystem _inner;
694	    private readonly PhysicsDemoScreen _screen;
695	    public bool IsEnabled { get; set; } = true;
696	
697	    public GatedGravitySystem(World world, IParallelRunner runner, PhysicsDemoScreen screen)
698	    {
699	        _screen = screen;
700	        // 1400 max-fall cap matches PhysicsDemoScreen.MaxFallSpeed to prevent
701	        // tunneling at high velocity.
702	        _inner = new GravitySystem(world, runner, worldGravity: 1200f, maxFallVelocity: 1400f);
703	    }
704	
705	    public void Update(GameState state)
706	    {
707	        if (!IsEnabled || !_screen.GravityEnabled) return;
708	        _inner.Update(state);
709	    }
710	
711	    public void Dispose()
712	    {
713	        _inner.Dispose();
714	        GC.SuppressFinalize(this);
715	    }
716	}
717	
718	/// Wraps TransformVelocitySystem so pause halts position updates without
719	/// dismantling the pipeline.
720	public class GatedVelocitySystem : ISystem<GameState>
721	{
722	    private readonly TransformVelocitySystem _inner;
723	    private readonly PhysicsDemoScreen _screen;
724	    public bool IsEnabled { get; set; } = true;
725	
726	    public GatedVelocitySystem(World world, IParallelRunner runner, PhysicsDemoScreen screen)
727	    {
728	        _screen = screen;
729	        _inner = new TransformVelocitySystem(world, runner);
730	    }
731	
