741	        GC.SuppressFinalize(this);
742	    }
743	}
744	
745	// ─── bounce resolution ────────────────────────────────────────────────────
746	
747	/// Custom resolution: subscribes to <see cref="CollisionMessage"/>, pushes the
748	/// base entity out by the MTV, then reflects its velocity along the contact
749	/// normal (with restitution). A floor-tagged collider adds an extra upward
750	/// impulse so the system stays in motion.
751	///
752	/// Replaces the engine's <see cref="TransformCollisionResolutionSystem{T}"/>
753	/// for this demo — that system zeros velocity along the normal (kinematic
754	/// "stop"), which would defeat the bouncing behaviour we want here.
755	public class BallBounceSystem : ISystem<GameState>
756	{
757	    private const float Restitution = 0.85f;
758	    private const float FloorBoost = 260f;
759	    private const float FlashImpactSpeed = 40f;  // min closing speed that counts as an impact
760	
761	    private readonly World _world;
762	    private readonly PhysicsDemoScreen _screen;
763	    private readonly List<CollisionMessage> _collisions = new();
764	
765	    public bool IsEnabled { get; set; } = true;
766	
767	    public BallBounceSystem(World world, PhysicsDemoScreen screen)
768	    {
769	        _world = world;
770	        _screen = screen;
771	        world.Subscribe<CollisionMessage>(OnCollision);
772	    }
773	
774	    private void OnCollision(in CollisionMessage msg) => _collisions.Add(msg);
775	
776	    public void Update(GameState state)
777	    {
778	        if (!IsEnabled)
779	        {
780	            _collisions.Clear();
781	            return;
782	        }
783	
784	        foreach (var msg in _collisions)
785	        {
786	            Resolve(msg);
787	        }
788	        _collisions.Clear();
789	    }
790	
791	    private void Resolve(CollisionMessage msg)
792	    {
793	        var entity = msg.BaseEntity;
794	        var other  = msg.CollidingEntity;
795	        if (!entity.IsAlive || !other.IsAlive) return;
796	
797	        // Walls have no velocity component (and shouldn't move); guard.
798	        if (!entity.Has<VelocityComponent>() || !entity.Has<TransformComponent>()) return;
799	
800	        // Filter blue↔blue: blue balls only collide with walls. They share a
801	        // layer (BlueBallLayer), so the detection system emits the message; we
802	        // discard it here. (Red↔blue is already filtered by layer mismatch.)
803	        if (entity.Has<BallTagComponent>() && other.Has<BallTagComponent>())
804	        {
805	            var a = entity.Get<BallTagComponent>().Type;
806	            var b = other.Get<BallTagComponent>().Type;
807	            if (a == BallType.Blue && b == BallType.Blue) return;
808	        }
809	
810	        ref var transform = ref entity.Get<TransformComponent>();
811	        ref var velocity = ref entity.Get<VelocityComponent>();
812	
813	        var normal = msg.ContactNormal;
814	        if (normal == Vector2.Zero) return;
815	        var penetration = msg.PenetrationDepth;
816	
817	        // SAT normal points from A's center toward B's center, i.e. "into the
818	        // collision" from A's perspective. Push A out along -normal.
819	        // For ball↔ball we apply half-push because the symmetric message
820	        // (A=B, B=A) will arrive too and push the other half; for ball↔wall
821	        // the wall is static and the swept self-skip ensures it never iterates
822	        // as A, so a single full push is correct here.
823	        var isBallVsBall = entity.Has<BallTagComponent>() && other.Has<BallTagComponent>();
824	        var pushScale = isBallVsBall ? 0.5f : 1f;
825	        transform.Translate(-normal * penetration * pushScale);
826	
827	        // Reflect velocity along the contact normal with restitution. Only do
828	        // it if velocity is moving INTO the collision (dot > 0); otherwise the
829	        // ball is already separating and we'd accidentally accelerate it.
830	        // The closing speed also gates the blink below, so a ball resting on the
831	        // floor (tiny per-frame contact) doesn't stay permanently lit.
832	        var impactSpeed = Vector2.Dot(velocity.Current, normal);
833	        if (impactSpeed > 0)
834	        {
835	            velocity.Current -= (1f + Restitution) * impactSpeed * normal;
836	        }
837	
838	        var hitFloor = other.Has<FloorTag>();
839	
840	        // Floor kick: extra upward impulse on top of the elastic bounce.
841	        if (_screen.FloorBoostEnabled && hitFloor)
842	        {
843	            // Subtract because Y-down: upward is -Y.
844	            velocity.Current.Y -= FloorBoost;
845	        }
846	
847	        // Blink on a genuine impact. The ball always blinks; the floor line only
848	        // blinks when its boost is on (matching its green "active" state).
849	        if (impactSpeed > FlashImpactSpeed)
850	        {
851	            Flash(entity);
852	            if (hitFloor && _screen.FloorBoostEnabled) Flash(_screen.FloorVisual);
853	        }
854	    }
855	
856	    /// (Re)trigger an entity's blink by resetting its flash timer to full.
857	    private static void Flash(Entity e)
858	    {
859	        if (!e.IsAlive || !e.Has<FlashComponent>()) return;
860	        ref var flash = ref e.Get<FlashComponent>();
861	        flash.Remaining = flash.Duration;
862	    }
863	
864	    public void Dispose()
865	    {
866	        _collisions.Clear();
867	        GC.SuppressFinalize(this);
868	    }
869	}
870	
871	// ─── flash / blink ─────────────────────────────────────────────────────────
872	
873	/// Drives <see cref="FlashComponent"/>: every frame it repaints a mesh entity's
874	/// vertex colors to either its resting <c>BaseColor</c> (when idle) or a value
875	/// lerped from <c>FlashColor</c> back toward <c>BaseColor</c> while a blink decays.
876	/// Writes colors in place (no allocation), so it must run in the update pipeline
877	/// before the mesh prep / render stage reads the vertices.
878	public class FlashSystem(World world)
879	    : AEntitySetSystem<GameState>(world.GetEntities().With<FlashComponent>().With<DrawComponent>().AsSet())
880	{
881	    protected override void Update(GameState state, in Entity entity)
882	    {
883	        ref var flash = ref entity.Get<FlashComponent>();
884	        var draw = entity.Get<DrawComponent>();
885	        if (draw.Vertices is not { Length: > 0 } vertices) return;
886	
887	        Color color;
888	        if (flash.Remaining > 0f)
889	        {
890	            flash.Remaining = MathF.Max(0f, flash.Remaining - state.Time);
891	            var t = flash.Duration > 0f ? flash.Remaining / flash.Duration : 0f;
892	            color = Color.Lerp(flash.BaseColor, flash.FlashColor, t);
893	        }
894	        else
895	        {
896	            color = flash.BaseColor;
897	        }
898	
899	        for (var i = 0; i < vertices.Length; i++)
900	            vertices[i].Color = color;
901	    }
902	}
903	
904	// ─── speed clamp ───────────────────────────────────────────────────────────
905	
906	/// Caps each ball's velocity magnitude. The floor boost adds fixed energy on every
907	/// bounce (the demo is "self-sustaining, not damped"), which otherwise compounds
908	/// until a ball is fast enough to tunnel through a wall in a single step. Clamping
909	/// the speed bounds the energy and keeps the balls contained. Runs after the bounce
910	/// system (the last writer of ball velocity) so the cap is the final word.
911	public class BallSpeedClampSystem(World world, float maxSpeed)
912	    : AEntitySetSystem<GameState>(world.GetEntities().With<BallTagComponent>().With<VelocityComponent>().AsSet())
913	{
914	    protected override void Update(GameState state, in Entity entity)
915	    {
916	        ref var velocity = ref entity.Get<VelocityComponent>();
917	        var speedSq = velocity.Current.LengthSquared();
918	        if (speedSq > maxSpeed * maxSpeed)
919	            velocity.Current = velocity.Current * (maxSpeed / MathF.Sqrt(speedSq));
920	    }
921	}
