146	            LayerDepth = layerDepth,
147	        });
148	        icon.Set(new DrawComponent { Type = DrawElementType.Sprite, Target = target });
149	        icon.Set<VisibleComponent>();
150	
151	        // Outline entity: invisible (transparent), supplies SimpleButton for hit-test +
152	        // DemoButton for click dispatch. TextEntity points at the icon so the interaction
153	        // system can recolor it on hover/active.
154	        var outline = world.CreateEntity();
155	        outline.Set(transform);
156	        outline.Set(new SimpleButtonComponent
157	        {
158	            Size = buttonSize,
159	            LineThickness = 0f,
160	            Color = Color.Transparent,
