61	    // Speed clamp keeps the self-sustaining floor-boost loop from compounding into
62	    // tunnelling speeds. Sits just above a full-height free-fall (~1030 px/s) so
63	    // normal bounces are untouched but runaway energy is capped.
64	    private const float MaxBallSpeed  = 1050f;
65	
