1	using System;
2	using System.Collections.Generic;
3	using DefaultEcs;
4	using DefaultEcs.System;
5	using Microsoft.Xna.Framework;
6	using MonoDreams.Component;
7	using MonoDreams.Component.Collision;
8	using MonoDreams.Extensions.Monogame;
9	using MonoDreams.Message;
10	using MonoDreams.State;
11	
12	namespace MonoDreams.System.Collision;
13	
14	/// <summary>
15	/// Collision detection system supporting both BoxColliderComponent (swept AABB) and ConvexColliderComponent (SAT).
16	/// Uses ColliderTagComponent marker component to query entities with either collider type.
17	/// Runs single-threaded because instance-level polygon buffers (_boxPolyBufA/_boxPolyBufB)
18	/// are not thread-safe.
19	/// </summary>
20	public class TransformCollisionDetectionSystem<TCollisionMessage> : ISystem<GameState>
21	    where TCollisionMessage : ICollisionMessage
22	{
23	    private readonly World _world;
24	    private readonly EntitySet _activeSet;
25	    private readonly IEnumerable<Entity> _targets;
26	    private readonly CreateCollisionMessageDelegate<TCollisionMessage> _createCollisionMessage;
27	
28	    public bool IsEnabled { get; set; } = true;
29	
30	    public TransformCollisionDetectionSystem(
31	        World world,
32	        CreateCollisionMessageDelegate<TCollisionMessage> createCollisionMessage)
33	    {
34	        _world = world;
35	        _createCollisionMessage = createCollisionMessage;
36	
37	        // Auto-tag entities when they get a collider component
38	        world.SubscribeEntityComponentAdded<BoxColliderComponent>(OnBoxColliderAdded);
39	        world.SubscribeEntityComponentAdded<ConvexColliderComponent>(OnConvexColliderAdded);
40	
41	        // ColliderTagComponent unifies BoxColliderComponent and ConvexColliderComponent into a single query, but each
42	        // type has its own passive/enabled semantics — those are checked at runtime in the
43	        // collision loop via GetCollider() rather than at query level.
44	        _activeSet = world.GetEntities()
45	            .With<ColliderTagComponent>()
46	            .With<TransformComponent>()
47	            .AsSet();
48	
49	        // All enabled collider entities are potential targets
50	        _targets = world.GetEntities()
51	            .With<ColliderTagComponent>()
52	            .With<TransformComponent>()
53	            .AsEnumerable();
54	    }
55	
56	    private static void OnBoxColliderAdded(in Entity entity, in BoxColliderComponent _)
57	    {
58	        if (!entity.Has<ColliderTagComponent>()) entity.Set<ColliderTagComponent>();
59	    }
60	
61	    private static void OnConvexColliderAdded(in Entity entity, in ConvexColliderComponent _)
62	    {
63	        if (!entity.Has<ColliderTagComponent>()) entity.Set<ColliderTagComponent>();
64	    }
65	
66	    public void Update(GameState state)
67	    {
68	        // Update world vertices for all ConvexColliderComponent entities (_targets is the superset of _activeSet)
69	        // TODO: static entities whose transforms never change could skip this with a dirty-flag optimization
70	        foreach (var target in _targets)
71	        {
72	            if (target.Has<ConvexColliderComponent>())
73	            {
74	                ref var convex = ref target.Get<ConvexColliderComponent>();
75	                convex.UpdateWorldVertices(target.Get<TransformComponent>());
76	            }
77	        }
78	
79	        // Test collisions
80	        foreach (var entity in _activeSet.GetEntities())
81	        {
82	            var colliderA = GetCollider(entity);
83	            if (colliderA == null || colliderA.Passive || !colliderA.Enabled) continue;
84	
85	            foreach (var target in _targets)
86	            {
87	                if (target == entity) continue;
88	
89	                var colliderB = GetCollider(target);
90	                if (colliderB == null || !colliderB.Enabled) continue;
91	                if (!colliderB.SharesLayerWith(colliderA)) continue;
92	
93	                var hasBoxA = entity.Has<BoxColliderComponent>();
94	                var hasBoxB = target.Has<BoxColliderComponent>();
95	
96	                if (hasBoxA && hasBoxB)
97	                {
98	                    // Box-vs-Box: existing swept AABB path (unchanged)
99	                    TestBoxVsBox(entity, target, colliderA, colliderB);
100	                }
101	                else
102	                {
103	                    // Any polygon pair: SAT
104	                    TestSAT(entity, target, colliderA, colliderB, hasBoxA, hasBoxB);
105	                }
106	            }
107	        }
108	    }
109	
110	    private void TestBoxVsBox(Entity entity, Entity target, IColliderComponent colliderA, IColliderComponent colliderB)
111	    {
112	        var boxA = entity.Get<BoxColliderComponent>();
113	        var transformA = entity.Get<TransformComponent>();
114	        var dynamicRect = CollisionRect.FromBounds(boxA.Bounds, transformA.Position);
115	        var displacement = transformA.Delta;
116	
117	        var boxB = target.Get<BoxColliderComponent>();
118	        var transformB = target.Get<TransformComponent>();
119	        var targetRect = CollisionRect.FromBounds(boxB.Bounds, transformB.Position);
120	
121	        var collides = DynamicRectVsRect(
122	            dynamicRect, displacement, targetRect,
123	            out var contactPoint, out var contactNormal, out var contactTime);
124	
125	        if (!collides || contactNormal == Vector2.Zero) return;
126	
127	        foreach (var layer in colliderB.SharedLayers(colliderA))
128	        {
129	            _world.Publish(_createCollisionMessage(entity, target, contactPoint, contactNormal, contactTime, 0f, layer));
130	        }
131	    }
132	
133	    // Reusable buffers for box-to-polygon conversion (avoids stackalloc scope issues)
134	    private readonly Vector2[] _boxPolyBufA = new Vector2[4];
135	    private readonly Vector2[] _boxPolyBufB = new Vector2[4];
136	
137	    private void TestSAT(Entity entity, Entity target, IColliderComponent colliderA, IColliderComponent colliderB, bool hasBoxA, bool hasBoxB)
138	    {
139	        // Broad-phase AABB rejection first (cheap)
140	        var aabbA = hasBoxA
141	            ? CollisionRect.FromBounds(entity.Get<BoxColliderComponent>().Bounds, entity.Get<TransformComponent>().Position)
142	            : entity.Get<ConvexColliderComponent>().BroadPhaseAABB;
143	        var aabbB = hasBoxB
144	            ? CollisionRect.FromBounds(target.Get<BoxColliderComponent>().Bounds, target.Get<TransformComponent>().Position)
145	            : target.Get<ConvexColliderComponent>().BroadPhaseAABB;
146	
147	        if (!aabbA.Intersects(aabbB)) return;
148	
149	        // Get world-space polygons for both entities
150	        Vector2[] polyA;
151	        Vector2[] polyB;
152	
153	        if (hasBoxA)
154	        {
155	            SATCollision.BoxToPolygon(entity.Get<BoxColliderComponent>(), entity.Get<TransformComponent>(), _boxPolyBufA);
156	            polyA = _boxPolyBufA;
157	        }
158	        else
159	        {
160	            polyA = entity.Get<ConvexColliderComponent>().WorldVertices;
161	        }
162	
163	        if (hasBoxB)
164	        {
165	            SATCollision.BoxToPolygon(target.Get<BoxColliderComponent>(), target.Get<TransformComponent>(), _boxPolyBufB);
166	            polyB = _boxPolyBufB;
167	        }
168	        else
169	        {
170	            polyB = target.Get<ConvexColliderComponent>().WorldVertices;
171	        }
172	
173	        if (!SATCollision.PolygonVsPolygon(polyA, polyB, out var contactNormal, out var penetrationDepth)) return;
174	
175	        // Contact point: centroid-midpoint approximation (not an exact contact point for SAT)
176	        var contactPoint = (SATCollision.PolygonCenter(polyA) + SATCollision.PolygonCenter(polyB)) / 2f;
177	
178	        foreach (var layer in colliderB.SharedLayers(colliderA))
179	        {
180	            _world.Publish(_createCollisionMessage(entity, target, contactPoint, contactNormal, 0f, penetrationDepth, layer));
181	        }
182	    }
183	
184	    private static bool RayVsRect(
185	        Vector2 rayOrigin, Vector2 rayDirection, CollisionRect target, out Vector2 contactPoint,
186	        out Vector2 contactNormal, out float closestHit)
187	    {
188	        closestHit = float.NaN;
189	        contactNormal = Vector2.Zero;
190	        contactPoint = Vector2.Zero;
191	
192	        var inverseDirection = Vector2.One / rayDirection;
193	        var closestDistance = (target.Position - rayOrigin) * inverseDirection;
194	        var furthestDistance = (target.Position + target.Size - rayOrigin) * inverseDirection;
195	
196	        if (float.IsNaN(furthestDistance.Y) || float.IsNaN(furthestDistance.X)) return false;
197	        if (float.IsNaN(closestDistance.Y) || float.IsNaN(closestDistance.X)) return false;
198	
199	        if (closestDistance.X > furthestDistance.X) (closestDistance.X, furthestDistance.X) = (furthestDistance.X, closestDistance.X);
200	        if (closestDistance.Y > furthestDistance.Y) (closestDistance.Y, furthestDistance.Y) = (furthestDistance.Y, closestDistance.Y);
201	
202	        if (closestDistance.X > furthestDistance.Y || closestDistance.Y > furthestDistance.X) return false;
203	
204	        closestHit = Math.Max(closestDistance.X, closestDistance.Y);
205	        var furthestHit = Math.Min(furthestDistance.X, furthestDistance.Y);
206	
207	        if (furthestHit < 0) return false;
208	
209	        contactPoint = rayOrigin + closestHit * rayDirection;
210	
211	        if (closestDistance.X > closestDistance.Y)
212	            contactNormal = inverseDirection.X < 0 ? new Vector2(1, 0) : new Vector2(-1, 0);
213	        else if (closestDistance.X < closestDistance.Y)
214	            contactNormal = inverseDirection.Y < 0 ? new Vector2(0, 1) : new Vector2(0, -1);
215	
216	        return true;
217	    }
218	
219	    public static bool DynamicRectVsRect(
220	        in CollisionRect dynamicRect, in Vector2 displacement, in CollisionRect staticRect,
221	        out Vector2 contactPoint, out Vector2 contactNormal, out float contactTime)
222	    {
223	        if (displacement is { X: 0, Y: 0 })
224	        {
225	            contactPoint = Vector2.Zero;
226	            contactNormal = Vector2.Zero;
227	            contactTime = 0;
228	            return dynamicRect.Intersects(staticRect);
229	        }
230	
231	        var expandedTarget = new CollisionRect(
232	            staticRect.Position - dynamicRect.Size / 2,
233	            staticRect.Size + dynamicRect.Size);
234	
235	        var potentialCollision = RayVsRect(
236	            dynamicRect.Center, displacement, expandedTarget, out contactPoint,
237	            out contactNormal, out contactTime);
238	
239	        return potentialCollision && contactTime < 1.0f;
240	    }
241	
242	    private static IColliderComponent GetCollider(Entity entity)
243	    {
244	        if (entity.Has<BoxColliderComponent>()) return entity.Get<BoxColliderComponent>();
245	        if (entity.Has<ConvexColliderComponent>()) return entity.Get<ConvexColliderComponent>();
246	        return null;
247	    }
248	
249	    public void Dispose()
250	    {
251	        _activeSet?.Dispose();
252	    }
253	}
