235	        {
236	            var n = ParseCount(msg.Text);
237	            if (n == _redCount) return;
238	            _redCount = n;
239	        }
240	        else if (msg.Input == _blueInput)
241	        {
242	            var n = ParseCount(msg.Text);
243	            if (n == _blueCount) return;
244	            _blueCount = n;
245	        }
246	        else return;
247	
248	        RebuildBalls();
249	    }
