367	    /// Despawns the current balls and spawns a fresh random set matching the
368	    /// current red/blue counts. Called on load, on reset, and whenever a count
369	    /// input changes.
370	    private void RebuildBalls()
371	    {
372	        foreach (var ball in _balls)
373	            if (ball.IsAlive) ball.Dispose();
374	        _balls.Clear();
375	
376	        for (var i = 0; i < _redCount; i++)  _balls.Add(CreateBall(BallType.Red));
377	        for (var i = 0; i < _blueCount; i++) _balls.Add(CreateBall(BallType.Blue));
378	    }
379	
380	    private Entity CreateBall(BallType type)
381	    {
382	        var radius = MinBallRadius + (float)_rng.NextDouble() * (MaxBallRadius - MinBallRadius);
383	        var spawn = RandomSpawn(radius);
384	
385	        var entity = _world.CreateEntity();
386	        entity.Set(new TransformComponent(spawn));
387	        entity.Set(new VelocityComponent(RandomVelocity()));
388	        entity.Set(new RigidBodyComponent(mass: 1f));
389	        entity.Set(new BallTagComponent { Type = type });
390	
391	        // Octagonal convex collider as a circle approximation. SAT handles
392	        // polygon-polygon collisions natively, so ball↔ball bounces look round
393	        // rather than square.
394	        var layer = type == BallType.Red ? RedBallLayer : BlueBallLayer;
395	        entity.Set(new ConvexColliderComponent(
396	            CircleVertices(radius, segments: 8),
397	            activeLayers: new HashSet<int> { layer }));
398	
399	        // Resting tint + the vivid color the ball blinks to on a wall hit (FlashSystem).
400	        var (color, flashColor) = BallColors(type);
401	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.95f };
402	        // Red balls are solid; blue balls are hollow — just their painted border.
403	        IMeshGenerator mesh = type == BallType.Blue
404	            ? new CircleOutlineMeshGenerator(Vector2.Zero, radius, BlueBallBorder, color, segments: 24)
405	            : new CircleMeshGenerator(Vector2.Zero, radius, color, segments: 24);
406	        draw.SetMeshData(mesh);
407	        entity.Set(draw);
408	        entity.Set(new FlashComponent(color, flashColor, FlashDuration));
409	        entity.Set<VisibleComponent>();
410	        return entity;
411	    }
412	
413	    /// A ball type's (resting tint, wall-hit flash tint). Single source of truth so
414	    /// the spawn code and the bounce system agree on a ball's colors.
415	    public static (Color Resting, Color Flash) BallColors(BallType type) => type == BallType.Red
416	        ? (SproutPalette.Crimson, new Color(255, 90, 80))
417	        : (SproutPalette.SkyBlue, new Color(150, 230, 255));
418	
419	    /// A random spawn point inside the boundary, kept a ball-radius clear of the walls.
420	    private Vector2 RandomSpawn(float radius)
421	    {
422	        var margin = radius + 8f;
423	        var x = MathHelper.Lerp(-BoundaryHalfWidth + margin,  BoundaryHalfWidth - margin,  (float)_rng.NextDouble());
424	        var y = MathHelper.Lerp(-BoundaryHalfHeight + margin, BoundaryHalfHeight - margin, (float)_rng.NextDouble());
425	        return new Vector2(x, y);
426	    }
427	
428	    private static Vector2[] CircleVertices(float radius, int segments)
429	    {
430	        var verts = new Vector2[segments];
431	        for (var i = 0; i < segments; i++)
432	        {
433	            var a = MathF.PI * 2f * i / segments;
434	            verts[i] = new Vector2(MathF.Cos(a) * radius, MathF.Sin(a) * radius);
435	        }
436	        return verts;
437	    }
