571	
572	    /// Adapter to the `CreateCollisionMessageDelegate<CollisionMessage>` shape that
573	    /// `TransformCollisionDetectionSystem` expects. Always emits Physics-type messages.
574	    private static CollisionMessage CreateCollisionMessage(
575	        Entity entity, Entity target,
576	        Vector2 contactPoint, Vector2 contactNormal,
577	        float contactTime, float penetrationDepth, int layer)
578	        => new(entity, target, contactPoint, contactNormal, contactTime, penetrationDepth, layer, CollisionType.Physics);
579	
580	    private SequentialSystem<GameState> CreateUpdateSystem()
581	    {
582	        // Reference physics pipeline order (per docs/CORE_TENETS.md §5):
583	        //   Movement → Velocity → Detection → Resolution → Commit
584	        // Movement here is gravity-only; ball↔ball/ball↔wall bouncing is the
585	        // custom resolution stage that subscribes to CollisionMessage.
586	        return new SequentialSystem<GameState>(
587	            new CursorInputSystem(_world),
588	            new IntrinsicSizingSystem(_world),
589	            new AutoLayoutSystem(_world, _viewportManager),
590	            new DemoButtonInteractionSystem(_world),
591	            new TextInputSystem(_world),
592	            new DemoIconRecolorSystem(_world),
593	            new ToggleSwitchSystem(_world),
594	            new PhysicsDemoInputSystem(this),
595	            new GatedGravitySystem(_world, _runner, this),
596	            new GatedVelocitySystem(_world, _runner, this),
597	            new TransformCollisionDetectionSystem<CollisionMessage>(_world, CreateCollisionMessage),
598	            new BallBounceSystem(_world, this),
599	            new BallSpeedClampSystem(_world, MaxBallSpeed),
600	            new FlashSystem(_world),
601	            new TransformCommitSystem(_world, _runner),
602	            new HierarchySystem(_world),
603	            new CursorPositionSystem(_world, _camera, _viewportManager),
604	            new CursorDrawPrepSystem(_world));
605	    }
