608	    {
609	        return new SequentialSystem<GameState>(
610	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering: false),
611	            new TextPrepSystem(_world, pixelPerfectRendering: false),
612	            new MeshPrepSystem(_world),
613	            new ButtonMeshPrepSystem(_world),
614	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
615	                RenderTargetID.Main, _renderTargets[RenderTargetID.Main], _camera),
616	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
617	                RenderTargetID.UI, _renderTargets[RenderTargetID.UI]),
618	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
619	                RenderTargetID.HUD, _renderTargets[RenderTargetID.HUD]),
