760	// ─── bounce resolution ────────────────────────────────────────────────────
761	
762	/// Custom resolution: subscribes to <see cref="CollisionMessage"/>, pushes the
763	/// base entity out by the MTV, then reflects its velocity along the contact
764	/// normal (with restitution). A floor-tagged collider adds an extra upward
765	/// impulse so the system stays in motion.
766	///
767	/// Replaces the engine's <see cref="TransformCollisionResolutionSystem{T}"/>
768	/// for this demo — that system zeros velocity along the normal (kinematic
769	/// "stop"), which would defeat the bouncing behaviour we want here.
770	public class BallBounceSystem : ISystem<GameState>
771	{
772	    private const float Restitution = 0.92f;     // energy retention per bounce (higher = less loss)
773	    private const float FloorBoost = 260f;
774	    private const float FlashImpactSpeed = 40f;  // min closing speed that counts as a wall impact
775	
776	    /// Bright pop both balls blink to when two balls collide — distinct from (and
777	    /// brighter than) the per-ball wall-hit tint, and fired regardless of speed.
778	    private static readonly Color BallCollisionFlashColor = new(255, 255, 235);
779	
780	    private readonly World _world;
781	    private readonly PhysicsDemoScreen _screen;
782	    private readonly List<CollisionMessage> _collisions = new();
783	
784	    public bool IsEnabled { get; set; } = true;
785	
786	    public BallBounceSystem(World world, PhysicsDemoScreen screen)
787	    {
788	        _world = world;
789	        _screen = screen;
790	        world.Subscribe<CollisionMessage>(OnCollision);
791	    }
792	
793	    private void OnCollision(in CollisionMessage msg) => _collisions.Add(msg);
794	
795	    public void Update(GameState state)
796	    {
797	        if (!IsEnabled)
798	        {
799	            _collisions.Clear();
800	            return;
801	        }
802	
803	        foreach (var msg in _collisions)
804	        {
805	            Resolve(msg);
806	        }
807	        _collisions.Clear();
808	    }
809	
810	    private void Resolve(CollisionMessage msg)
811	    {
812	        var entity = msg.BaseEntity;
813	        var other  = msg.CollidingEntity;
814	        if (!entity.IsAlive || !other.IsAlive) return;
815	
816	        // Walls have no velocity component (and shouldn't move); guard.
817	        if (!entity.Has<VelocityComponent>() || !entity.Has<TransformComponent>()) return;
818	
819	        // Filter blue↔blue: blue balls only collide with walls. They share a
820	        // layer (BlueBallLayer), so the detection system emits the message; we
821	        // discard it here. (Red↔blue is already filtered by layer mismatch.)
822	        if (entity.Has<BallTagComponent>() && other.Has<BallTagComponent>())
823	        {
824	            var a = entity.Get<BallTagComponent>().Type;
825	            var b = other.Get<BallTagComponent>().Type;
826	            if (a == BallType.Blue && b == BallType.Blue) return;
827	        }
828	
829	        ref var transform = ref entity.Get<TransformComponent>();
830	        ref var velocity = ref entity.Get<VelocityComponent>();
831	
832	        var normal = msg.ContactNormal;
833	        if (normal == Vector2.Zero) return;
834	        var penetration = msg.PenetrationDepth;
835	
836	        // SAT normal points from A's center toward B's center, i.e. "into the
837	        // collision" from A's perspective. Push A out along -normal.
838	        // For ball↔ball we apply half-push because the symmetric message
839	        // (A=B, B=A) will arrive too and push the other half; for ball↔wall
840	        // the wall is static and the swept self-skip ensures it never iterates
841	        // as A, so a single full push is correct here.
842	        var isBallVsBall = entity.Has<BallTagComponent>() && other.Has<BallTagComponent>();
843	        var pushScale = isBallVsBall ? 0.5f : 1f;
844	        transform.Translate(-normal * penetration * pushScale);
845	
846	        // Reflect velocity along the contact normal with restitution. Only do
847	        // it if velocity is moving INTO the collision (dot > 0); otherwise the
848	        // ball is already separating and we'd accidentally accelerate it.
849	        // The closing speed also gates the wall-hit blink below, so a ball resting
850	        // on the floor (tiny per-frame contact) doesn't stay permanently lit.
851	        var impactSpeed = Vector2.Dot(velocity.Current, normal);
852	        if (impactSpeed > 0)
853	        {
854	            velocity.Current -= (1f + Restitution) * impactSpeed * normal;
855	        }
856	
857	        var hitFloor = other.Has<FloorTag>();
858	
859	        // Floor kick: extra upward impulse on top of the elastic bounce.
860	        if (_screen.FloorBoostEnabled && hitFloor)
861	        {
862	            // Subtract because Y-down: upward is -Y.
863	            velocity.Current.Y -= FloorBoost;
864	        }
865	
866	        // Two balls colliding always pop a bright flash on BOTH balls — independent
867	        // of which ball is this message's base entity and of the closing speed.
868	        // Wall hits keep the per-ball tint, gated by a minimum closing speed so a
869	        // ball resting on the floor doesn't stay permanently lit.
870	        if (isBallVsBall)
871	        {
872	            Flash(entity, BallCollisionFlashColor);
873	            Flash(other, BallCollisionFlashColor);
874	        }
875	        else if (impactSpeed > FlashImpactSpeed)
876	        {
877	            Flash(entity, PhysicsDemoScreen.BallColors(entity.Get<BallTagComponent>().Type).Flash);
878	            if (hitFloor && _screen.FloorBoostEnabled) Flash(_screen.FloorVisual);
879	        }
880	    }
881	
882	    /// (Re)trigger an entity's blink, keeping its existing <see cref="FlashComponent.FlashColor"/>.
883	    private static void Flash(Entity e)
884	    {
885	        if (!e.IsAlive || !e.Has<FlashComponent>()) return;
886	        ref var flash = ref e.Get<FlashComponent>();
887	        flash.Remaining = flash.Duration;
888	    }
889	
890	    /// (Re)trigger an entity's blink with an explicit color. <see cref="FlashSystem"/> shows
891	    /// <c>BaseColor</c> when idle, so overwriting <c>FlashColor</c> here only colors the blink
892	    /// this call starts — letting wall hits and ball↔ball hits blink different colors.
893	    private static void Flash(Entity e, Color flashColor)
894	    {
895	        if (!e.IsAlive || !e.Has<FlashComponent>()) return;
896	        ref var flash = ref e.Get<FlashComponent>();
897	        flash.FlashColor = flashColor;
898	        flash.Remaining = flash.Duration;
899	    }
900	
901	    public void Dispose()
902	    {
903	        _collisions.Clear();
904	        GC.SuppressFinalize(this);
905	    }
906	}
907	
908	// ─── flash / blink ─────────────────────────────────────────────────────────
909	
910	/// Drives <see cref="FlashComponent"/>: every frame it repaints a mesh entity's
911	/// vertex colors to either its resting <c>BaseColor</c> (when idle) or a value
912	/// lerped from <c>FlashColor</c> back toward <c>BaseColor</c> while a blink decays.
913	/// Writes colors in place (no allocation), so it must run in the update pipeline
914	/// before the mesh prep / render stage reads the vertices.
915	public class FlashSystem(World world)
916	    : AEntitySetSystem<GameState>(world.GetEntities().With<FlashComponent>().With<DrawComponent>().AsSet())
917	{
918	    protected override void Update(GameState state, in Entity entity)
919	    {
920	        ref var flash = ref entity.Get<FlashComponent>();
921	        var draw = entity.Get<DrawComponent>();
922	        if (draw.Vertices is not { Length: > 0 } vertices) return;
923	
924	        Color color;
925	        if (flash.Remaining > 0f)
926	        {
927	            flash.Remaining = MathF.Max(0f, flash.Remaining - state.Time);
928	            var t = flash.Duration > 0f ? flash.Remaining / flash.Duration : 0f;
929	            color = Color.Lerp(flash.BaseColor, flash.FlashColor, t);
930	        }
931	        else
932	        {
933	            color = flash.BaseColor;
934	        }
935	
936	        for (var i = 0; i < vertices.Length; i++)
937	            vertices[i].Color = color;
938	    }
939	}
940	
941	// ─── speed clamp ───────────────────────────────────────────────────────────
942	
943	/// Caps each ball's velocity magnitude. The floor boost adds fixed energy on every
944	/// bounce (the demo is "self-sustaining, not damped"), which otherwise compounds
945	/// until a ball is fast enough to tunnel through a wall in a single step. Clamping
946	/// the speed bounds the energy and keeps the balls contained. Runs after the bounce
947	/// system (the last writer of ball velocity) so the cap is the final word.
948	public class BallSpeedClampSystem(World world, float maxSpeed)
949	    : AEntitySetSystem<GameState>(world.GetEntities().With<BallTagComponent>().With<VelocityComponent>().AsSet())
950	{
951	    protected override void Update(GameState state, in Entity entity)
952	    {
953	        ref var velocity = ref entity.Get<VelocityComponent>();
954	        var speedSq = velocity.Current.LengthSquared();
955	        if (speedSq > maxSpeed * maxSpeed)
956	            velocity.Current = velocity.Current * (maxSpeed / MathF.Sqrt(speedSq));
957	    }
958	}
959

