133	/// <summary>
134	/// Generates a line mesh with configurable thickness.
135	/// </summary>
136	public class LineMeshGenerator : IMeshGenerator
137	{
138	    public Vector2 Start { get; set; }
139	    public Vector2 End { get; set; }
140	    public float Thickness { get; set; }
141	    public Color Color { get; set; }
142	
143	    public LineMeshGenerator(Vector2 start, Vector2 end, float thickness, Color color)
144	    {
145	        Start = start;
146	        End = end;
147	        Thickness = thickness;
148	        Color = color;
149	    }
150	
151	    public MeshData Generate()
152	    {
153	        var vertices = new List<VertexPositionColor>();
154	        var indices = new List<int>();
155	        int indexOffset = 0;
156	
157	        AddLine(vertices, indices, Start, End, Thickness, Color, ref indexOffset);
158	
159	        return new MeshData(vertices.ToArray(), indices.ToArray());
160	    }
161	
162	    public static void AddLine(
163	        List<VertexPositionColor> vertices,
164	        List<int> indices,
165	        Vector2 start,
166	        Vector2 end,
167	        float thickness,
168	        Color color,
169	        ref int indexOffset)
170	    {
171	        Vector2 direction = end - start;
172	        Vector2 perpendicular = new(-direction.Y, direction.X);
173	        perpendicular.Normalize();
174	        perpendicular *= thickness / 2;
175	
176	        vertices.Add(new VertexPositionColor(new Vector3(start + perpendicular, 0), color));
177	        vertices.Add(new VertexPositionColor(new Vector3(start - perpendicular, 0), color));
178	        vertices.Add(new VertexPositionColor(new Vector3(end - perpendicular, 0), color));
179	        vertices.Add(new VertexPositionColor(new Vector3(end + perpendicular, 0), color));
180	
181	        indices.Add(indexOffset);
182	        indices.Add(indexOffset + 1);
183	        indices.Add(indexOffset + 2);
184	
185	        indices.Add(indexOffset);
186	        indices.Add(indexOffset + 2);
187	        indices.Add(indexOffset + 3);
188	
189	        indexOffset += 4;
190	    }
191	}
