308	/// <summary>
309	/// Generates a filled rectangle mesh.
310	/// </summary>
311	public class FilledRectangleMeshGenerator : IMeshGenerator
312	{
313	    public Rectangle Bounds { get; set; }
314	    public Color Color { get; set; }
315	
316	    public FilledRectangleMeshGenerator(Rectangle bounds, Color color)
317	    {
318	        Bounds = bounds;
319	        Color = color;
320	    }
321	
322	    public MeshData Generate()
323	    {
324	        var vertices = new VertexPositionColor[]
325	        {
326	            new(new Vector3(Bounds.Left, Bounds.Top, 0), Color),
327	            new(new Vector3(Bounds.Right, Bounds.Top, 0), Color),
328	            new(new Vector3(Bounds.Right, Bounds.Bottom, 0), Color),
329	            new(new Vector3(Bounds.Left, Bounds.Bottom, 0), Color)
330	        };
