// Resting-contact handling so dense piles settle instead of jittering. Below
// RestThreshold a contact is "resting": restitution drops to 0 (cancel only the
// inward normal velocity) instead of bouncing, so gravity's ~20 px/s per-frame
// nudge no longer micro-bounces a ball forever. PenetrationSlop + PositionCorrection
// do Baumgarte-style soft separation — ignore sub-pixel overlap and push out only
// a fraction of the rest per frame — so packed neighbours stop shoving each other
// around (the overlap shimmer). All three engage only at low speed, so active
// bouncing (and the floor-boost showcase) is untouched.
private const float RestThreshold      = 50f;   // closing speed below which a contact is "resting"
private const float PenetrationSlop    = 0.5f;  // overlap (px) left uncorrected
private const float PositionCorrection = 0.5f;  // fraction of the remaining overlap pushed out per frame

